-- ============================================================
-- Adventures (resuelve guía por (slug, título); descripción como clave)
-- sort_order 1-based correlativo por guía
-- ============================================================
INSERT INTO gg_adventures (guide_id, description, is_important, is_optional, sort_order)
SELECT gr.id, x.description, x.is_important, x.is_optional, x.sort_order
FROM gg_games g, gg_guides gr, (VALUES
  ('chrono-cross', '(AW) Termina', E'✓ Ve a la estatua en lo mas alto del pueblo, habla con el tipo que la esta limpiando, y consigue a Kid (Personaje 5/45) y obtendrás el Tele Porter (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Termina', E'✓ Obten el marco Tea for Three (Marco 5/15)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Termina', E'✓ Ve a la parte mas al este del pueblo, dale las flores a Glenn', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Termina', E'✓ Aquí debes decidir cual de los 3 personajes quieres reclutar para infiltrarte en el Viper Manor, No los puedes conseguir a todos en una partida, deberás iniciar una partida (NG+) para los 2 que falten', FALSE, FALSE, 4),
  ('chrono-cross', '(AW) Termina', E'Opción 1: Consigue a Guile (Personaje 6/45), Habla con el en el bar. Ve al cementerio de Termina, encuentra el barco de Korcha y sube por el rompeolas', TRUE, FALSE, 5),
  ('chrono-cross', '(AW) Termina', E'Opción 2: Consigue a Pierre (Personaje 8/45), en la Herrería, primero debes conseguir el Heros Medal (Item /56) del del niño que juega afuera y devolvérselo a Pierre, Ve a la puerta principal de Viper Manor', TRUE, FALSE, 6),
  ('chrono-cross', '(AW) Termina', E'Opción 3: Consigue a Nikki (Personaje 7/45), habla con todos en el barco de Magical Dreamers hasta que llegue Miki. Ve al Bosque Shadow, consigue la Aroma Pouch (Item /56) y úsalo para mover a los monstruitos hacia el monstruo-planta gigante, en la cueva de la cascada puedes encontrar el Skullduggery (Marco 6/15) y recoge la Angry Scapula (Item /56) de Skelly, avanza por el camino que bloqueaba el monstruo, mueve la roca para detener a los insectos, avanza hasta salir por el pozo', TRUE, FALSE, 7),
  ('chrono-cross', '(AW) Fossil Valley', E'✓ Obten el Heavy Skull (Item /56) de Skelly', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Fossil Valley', E'✓ Obten las Bellflower (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Fossil Valley', E'✓ Obten el Big Egg (Item /56) cerca del pajaro', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Hydra Swamp', E'✓ Ve al noroeste, encuentra a un chico que te dara el Safety Gear (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Another World', E'✓ Lucharas con Karsh, Solt y Peppor', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Another World', E'✓ Nombra a Kid pero NO la reclutes aun (rechazala 3 veces)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Another World', E'✓ Leena (Personaje 3/45) y Poshul (Personaje 4/45) se te unirán ahora, (es la única manera de conseguir a Leena)', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Another World', E'✓ Ve donde conseguiste el Shark Tooth Amulet y muéstraselo al predicador, se te unirá Mojo (Personaje 2/45) al salir de allí', FALSE, FALSE, 4),
  ('chrono-cross', '(HW) Lizard Rock', E'Escamas de Komodo', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Arni Village', E'✓ Obten la Shellfish Window Frame (Marco 4/15) de la tienda de elements', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Arni Village', E'✓ Consigue la Komodo Scale (Item /56) dandole la razon al vendedor y regalasela al muchacho', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Arni Village', E'✓ Coge el Shark Tooth Amulet (Item /56) de uno de los tipos de las casas de la derecha', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Arni Village', E'✓ Consigue el Heckran Bone (Item /56) de debajo de la cama del bar', FALSE, FALSE, 4),
  ('chrono-cross', '(HW) Arni Village', E'✓ Habla con la camarera del bar la de los poemas y finalmente NO reclutes a Poshul aun', FALSE, FALSE, 5),
  ('chrono-cross', 'Final oculto: Programmers Ending (Final 1/11)', E'Cuando despiertes crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer inmediatamente sin reclutar compañeros', TRUE, FALSE, 1),
  ('chrono-cross', 'El Sueño', E'Partidas guardadas', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: General Kid (Final 2/11)', E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer antes de infiltrarte en Viper Manor', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Infiltración a Viper Manor', E'✓ La puerta principal esta cerrada\n✓ La llave Manor Key (Item /56) esta en la parte superior derecha del establo de alimentación de dragones', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Infiltración a Viper Manor', E'✓ Debes jugar al juego de alimentar dragones al menos una vez, si quieres alimentarlos todos sin fallar, puedes usar el Time Shifter (Item /56) que puedes obtener en la partida (NG+)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Gira la estatua de la serpiente, y cae en la trampa', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Lucha con los guardias, coge su ropa y entra en las habitaciones de la parte izquierda\n✓ En la cocina, habla con Glenn, ve a su habitación, y te escribirá la combinación de la estatua', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Viper Manor', E'✓ En las habitaciones de la derecha, recoge todos los artículos y el pendiente para caer en otra trampa\n✓ Lucha con los bichos de Luccia\n✓ Libera al criatura que esta enjaulada', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Viper Manor', E'✓ La habitación que esta al lado del laboratorio podrás conseguir el Decor Shield (Item /56), si la colocas en la armadura sin escudo encontraras una habitación secreta', FALSE, FALSE, 4),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Vuelve a la entrada y usa la combinación apropiada en la estatua de la serpiente\n✓ Ve al oeste, a la biblioteca, veras a Balthasar (Chrono Trigger), lucha con Marcy\n✓ Obtén el marco Porres Furnace (Marco 7/15)', FALSE, FALSE, 5),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Habla con el viejo, vuelve a la habitación grande, busca en las columnas un botón que accione el ascensor\n✓ Lucha con los guardias, toma el ascensor y pasa la puerta\n✓ Lucha contra Lynx, habrá unas cuantas escenas', FALSE, FALSE, 6),
  ('chrono-cross', 'Final oculto: The True Hero (Final 3/11)', E'✓ Este final tiene 2 variantes, las variantes dependerán de que decisión tomas en Guldove', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: The True Hero (Final 3/11)', E'Opción 1: No salvar a Kid. Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+, Vencer al Time Devourer inmediatamente después de que Kid quede envenenada', TRUE, FALSE, 2),
  ('chrono-cross', 'Final oculto: The True Hero (Final 3/11)', E'Opción 2: Salvar a Kid. Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+, Vencer al Time Devourer inmediatamente despues de encontrar la cura en Hydra Marsh y Kid se haya recuperado', TRUE, FALSE, 3),
  ('chrono-cross', '(AW) Guldove', E'✓ Tendrás que elegir entre salvar o NO salvar a kid recibirás el Astral Amulet (Item /56), dependiendo de la decisión podrás obtener nuevos personajes distintos en ambos casos', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove', E'✓ En ambos casos debes hablar con el Chaman y el enano del bar el cual te dará el Green Tinkler (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Guldove', E'Opción 1: No salvar a Kid: Habla con Korcha y luego con Macha, toma el barco de Kocha hacia Termina, en la entrada veras a Glenn. Vuelve al barco, conseguirás a Glenn (Personaje 9/45) y Macha (Personaje 10/45), Macha te dará el Tropical Paradise (Marco 8/15). Haz el capitulo: 15.- (AW) Piratas Fantasmas, luego vuelve a Guldove para ver al Doc y Kid. Se te unirá el Doc (Personaje 11/45). Finalmente puedes hacer el capitulo: 14.- (HW) Bosque Hydra', TRUE, FALSE, 3),
  ('chrono-cross', '(AW) Guldove', E'Opción 2: Salvar a Kid: Se te une Korcha (Personaje 12/45), Toma el barco hacia Termina, en la entrada veras a Glenn, Ve a la Playa Opassa, Haz el capitulo: 14.- (HW) Bosque Hydra, vuelve a Guldove, asegurate de darle el medicamento a Kid y luego trata de captura a Mel (Personaje 13/45) si es que las quieres conseguir, ella te da el Guldovian Stitch (Marco 9/15), para ello deveras hablar con Orla y el portero del Chaman luego ve al escondite de Mel. Viaja a Termina, escucha a Glenn Vuelve al bote aceptando a Korcha NUEVAMENTE y viaja a Guldove a la casa de Mel (Por fin se une la bastarda). Finalmente ve al capitulo: 15.- (AW) Piratas Fantasmas', TRUE, FALSE, 4),
  ('chrono-cross', '(HW) Bosque Hydra', E'✓ Ve al Hydra Marsh, lucha con Beeba, obtén la Beeba Flute (Item /56) y úsala al norte de todo, Lucha contra el Wingapede y cae por el agujero en donde acabas de pelear', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Bosque Hydra', E'No Salvar a Kid: Al caer por el agujero veras que el pulpo ya se comió a Razzly', TRUE, FALSE, 2),
  ('chrono-cross', '(HW) Bosque Hydra', E'Salvar a Kid: Lucha con el pulpo y consigue a Razzly el hada (Personaje 14/45), sigue por la parte norte luego este, lucha contra la Hydra (SIN Razzly en tu equipo), obtendrás la Hydra Humour (Item /56)', TRUE, FALSE, 3),
  ('chrono-cross', '(AW) Piratas Fantasmas', E'✓ Ve a la zona nublosa entre El Nido y el The Dead Sea\n✓ Cuando ataquen los fantasmas, observa que la puerta principal esta cerrada', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Piratas Fantasmas', E'✓ Mata a todos los esqueletos y habla con los piratas para encontrar una llave', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Piratas Fantasmas', E'✓ Durante el recorrido encontraras a la criatura que liberaste, si la capturas reclutaras a Pip (Personaje 15/45)\n✓ Llega a la cubierta, lucha con el Diamond Jar', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Guldove | Termina | Viper Manor', E'✓ Ve a guldove y consigue la Pelvic Bone (Item /56) de Skelly de la niña comerciante cerca del barco', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove | Termina | Viper Manor', E'✓ Ve a Termina y consigue a Greco (Personaje 16/45) en la casa del cementerio', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Guldove | Termina | Viper Manor', E'✓ Ve a Viper Manor y busca Luccia (Personaje 17/45) para reclutarla', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Arni Village', E'✓ Ve a Arni Village habla con la camarera del bar y te dará el Book of Poems (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Arni Village', E'✓ Habla con el viejo pescador cerca de Leena, te llevara a la Isla del Dragon de Agua\n✓ Aquí, ve hasta el Dragon de Agua y te dará el Ice Breath (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Arni Village', E'✓ Cuando vuelvas a (AW) ve a Arni Village y entrégale a la camarera el Book of Poems', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Costa Este de El Nido', E'✓ Cruza el Monte Piro, usa el Ice Breath para congelar la lava\n✓ Te recomiendo recoger todos los cofres primero antes de congelar todo\n✓ Cruza todo el Monte hasta llegar a Fort Dragonia', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: The Magical Dreamers (Final 4/11)', E'Antes de terminar la Fortaleza, crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer con la siguiente formación Nikki, Razzly y Kid, Para reemplazar a Serge del equipo puede usar el Relief Charm (Item /56) que obtienes al iniciar la partida NG+', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Fort Dragonia', E'✓ Resuelve todos los puzzles y jefes\n✓ Debes vencer al SOL (Hincha Pelotas), toma el ascensor\n✓ Lynx y Viper estarán aquí, continua la historia...', FALSE, FALSE, 1),
  ('chrono-cross', 'Mundo Abstracto y el Más Allá', E'✓ Hola Lynx (Personaje 18/45), toma una manzana del árbol y Sprigg vendrá\n✓ Entra en su casa y podrás reclutar a Sprigg (Personaje 19/45)\n✓ Ve al norte, sigue a Serge a cada puerta que vaya (en tu piso)\n✓ Harle (Personaje 20/45) se te une, avanza, escapa por el agujero y aparecerás en Hydra Marsh', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: New Beginnings (Final 5/11)', E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer con Lynx', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Termina', E'✓ Intenta cruzar el portal para ir a (HW) en la playa luego intenta cruzar el Fossil Valley\n✓ Ve a Arni Village, habla con Marge y lucha contra Radius (Personaje 21/45) para reclutarlo', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Termina', E'✓ Cruza el Fossil Valley y consigue el Infrared Vision (Marco 10/15)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Termina', E'✓ Ve Termina para reclutara Zappa (Personaje 22/45) este te data el Smith Spirit (Item /56) y a Van (Personaje 23/45)', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Viper Manor', E'✓ Con Radius ve a Termina a buscar a Norris, luego entra por el Shadow Forest, después de hablar con el niño salvar a un hombre, golpeando a un insecto ahogado, y te dará el Mushroom (Item /56). Puedes obtener Funguy (Personaje 40/45) si le das el champiñón al hombre de la cueva', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Viper Manor', E'✓ Ve por las mazmorras, si no puedes pasar tendrás que ir por la entrada principal y bajar por el pozo. Habla con Norris (Personaje 24/45), se te unirá si Radius esta contigo', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Viper Manor', E'✓ Ve a Termina, ahora podrás usar un bote inflable donde estaba el barco de Nikki', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Nido Triangle | Sky Dragon Isle | Marbule', E'✓ Ve al Nido Triangle, nada hasta el fondo y obtén el Star Fragment (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Nido Triangle | Sky Dragon Isle | Marbule', E'✓ Ve a Sky Dragon Isle e intenta abrir el cofre, lucha contra Starky (Personaje 25/45) y véncelo para reclutarlo, obtén Our Favorite Martian (Marco 11/15)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) El Zelbess de Fargo', E'✓ Intenta cruzar la puerta del fondo del barco, Fargo te debe dar permiso, abre la puerta siguiente y veras a un orejón que hace aseo, háblale\n✓ Ve a pedirle a Fargo permiso para cruzar la puerta, te hará juega a la Roulette y perderás. ve a la primera puerta debajo del casino, veras algo sospechoso', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) El Zelbess de Fargo', E'✓ Mira el show de Sneff, convertirá a alguien en gato, sale y vuelve a entrar para que Sneff te convierta en gato\n✓ Mientras seas gato y le hablas al gato de la cocina podrás obtener el Monsters Mouth (Marco 13/15)\n✓ Entra en el en la habitación que esta debajo de la ruleta, roba el Handle (Item /56)\n✓ Ve donde Sneff y que te vuelva a convertir, juega a la Roulette con Fargo otra vez. Perderá, ahora cruza esa puerta', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) El Zelbess de Fargo', E'✓ Si ganas los 3 combates del SLAM podrás reclutar a Janice (Personaje 26/45)\n✓ Lucha contra el Sabio y obtén la Fiddler Crab (Item /56)\n✓ Ve al casino donde esta la ruleta, luego ve a la segunda habitación bajando las escaleras y reclutaras a Sneff (Personaje 27/45)\n✓ Sube a la cubierta y luego por el mástil, aquí se unirá Irenes (Personaje 28/45)', FALSE, FALSE, 3),
  ('chrono-cross', '(HW) Mar del Edén', E'✓ ve al The Dead Sea y usa la Fiddler Crab, entra y veras la Masamune\n✓ Despues de hablar, ve a la Hermits Hideaway (HW), habla con Radius y recibe el Garais Keepsake (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Isla Maldita', E'✓ Llega al espejo de la izquierda del todo (bajando por el esqueleto serpiente)\n✓ Lucha con Garai (a llorar a la playa)\n✓ Obtén la Einlanzer (Item /56) y úsala para destruir la Masamune en Dead Sea', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Mar del Edén', E'✓ Ve al The Dead Sea, recoge todos los cofres\n✓ Habla con el fantasma y se le caerá algo, recógelo y Obtén el Station Pass (Item /56) con este ítem podrá obtener el Medical Book (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(HW) Mar del Edén', E'✓ Obtén el Prop Sword (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(HW) Mar del Edén', E'✓ Lucha con Miguel, y la ciudad será destruida (el Dragon del Cielo te salvara)', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', E'✓ Viaja por el portal de la playa a (AW)\n✓ ve a Hydra Marshes y explora todo lucha con jefes obtendrás una habilidad especial, mas adelante en una lagunilla obtén el Life Sparkle (Ítem /56) y Busca el Good Backbone (Ítem /56) de Skelly en una cueva (por la zona este)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', E'✓ Ve al bar de Termina, hay una habitación secreta, aquí podrás reclutar a Zoah (Personaje 30/45) o Karsh (Personaje 31/45), si quieres obtener a los 2 deveras terminar el juego e iniciar (NG+) Pero si eliges a Karsh, Zoha se te unirá en el S.S Zelbess también obtendrás el Tear of Hate (Ítem /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', E'Opción 1: Consigue a Zoah', TRUE, FALSE, 3),
  ('chrono-cross', '(AW) Hydra Swamp | Termina', E'Opción 2: Consigue a Karsh', TRUE, FALSE, 4),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Ve a Viper Manor, habla con Norris en la habitación del oeste de la entrada y te dará la Prison Key (Item /56)', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Si vas a la cárcel, encontraras una la Parlor Key (Item /56)', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Ve a las alcantarillas desde la cocina, encuentra y apaga la válvula\n✓ Vuelve a la primera sección, ahora ya puedes cruzar, y apaga la segunda válvula\n✓ En la siguiente pantalla, sube la válvula y vuelve al otro lado\n✓ Bájala, procede, y lucharas contra un bicho gordo, procede subir las escaleras', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Viper Manor', E'✓ Lucharas contra Dark Orcha para rescatar a Riddel, luego se te unirá Orcha (Personaje 32/45)\n✓ Sigue recto hacia la biblioteca, lucharas con Grovyc y Mecha\n✓ Escapa hacia la biblioteca, lucha con Mecha otra vez, y escapa por la ventana\n✓ Grobyc (Personaje 33/45) se unirá a tu grupo', FALSE, FALSE, 4),
  ('chrono-cross', 'Final oculto: Onward Dragoons (Final 6/11)', E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer inmediatamente después de rescatar a Riddel', TRUE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', E'✓ Ve a Guldove y Lucha con Orlha y conseguirás su Sapphire Brooch (Ítem /56), devuélvesela cuando seas Serge de nuevo, y se te unirá\n✓ Dale al Doc. el libro para desbloquear su habilidad', FALSE, FALSE, 1),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', E'✓ Ve Water Dragon Isle y a Un tipo te dará el Sturdy Ribs (Item /56) de Skelly', FALSE, FALSE, 2),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', E'✓ Ve a Isle of the Damned, recoge los Mixed Bones (Ítem /56) de Skelly en la cueva al noroeste de la primera pantalla', FALSE, FALSE, 3),
  ('chrono-cross', '(AW) Guldove | Water Dragon Isle | Isle of the Damned | Termina', E'✓ Si ya tienes todas las 6 partes de Skelly (Heavy Skull, Pelvic Bone, Mixed Bones, Angry Scapula, Good Backbone, Sturdy Ribs) ve a Termina a la casa de la derecha de la estatua de Viper, y se te unirá Skelly (Personaje 34/45) si hablas con la abuela', FALSE, FALSE, 4),
  ('chrono-cross', '(AW) Hermits Hideaway', E'✓ Habla con Riddel (Personaje 35/45) y se te unirá\n✓ Se te unirán Viper (Personaje 36/45), Fargo (Personaje 37/45) y Mercy (Personaje 38/45)... (Zoah o Karsh)', FALSE, FALSE, 1),
  ('chrono-cross', 'Final oculto: Darkened Fate (Final 7/11)', E'Crea un guardado independiente de la partida principal, cuando termines el juego carga esta partida con el Continue+. Vencer al Time Devourer después de que Harle abandona tu grupo', TRUE, FALSE, 1)
) AS x(game_slug, guide_title, description, is_important, is_optional, sort_order)
WHERE g.slug = x.game_slug AND gr.game_id = g.id AND gr.title = x.guide_title
ON CONFLICT DO NOTHING;

